import json, sys, math, time
from urllib.parse import urlencode
from urllib.request import urlopen, Request
from urllib.error import HTTPError, URLError
BASE='https://federation.ccdi.cancer.gov/api/v1'
PATH='/sample-diagnosis'
PARAMS={'search':'brain','per_page':100}

def get(page):
    params=dict(PARAMS,page=page)
    url=BASE+PATH+'?'+urlencode(params)
    req=Request(url, headers={'Accept':'application/json','User-Agent':'codex-metadata-summary/1.0'})
    with urlopen(req, timeout=90) as r:
        return json.loads(r.read().decode()), dict(r.headers.items()), url

def field_value(v):
    if v is None: return None
    if isinstance(v, dict) and 'value' in v: return v.get('value')
    return v

def id_key(obj):
    if not obj: return None
    ns=obj.get('namespace') or {}
    return '|'.join(str(x) for x in [ns.get('organization'), ns.get('name'), obj.get('name')])

def sample_key(s, source):
    return source+'|sample|'+id_key(s.get('id'))

def subject_key(s, source):
    subj=s.get('subject')
    k=id_key(subj) if subj else None
    return source+'|subject|'+k if k and 'None' not in k else None

def parse_age_days(s):
    md=s.get('metadata') or {}
    v=field_value(md.get('age_at_diagnosis'))
    # Could be array/list or string/number. Use first parseable if list.
    vals = v if isinstance(v, list) else [v]
    out=[]
    for x in vals:
        if x is None or x=='': continue
        try:
            f=float(x)
            if math.isfinite(f): out.append(f)
        except (TypeError, ValueError):
            pass
    return out

records=[]
errors=[]
page_summaries=[]
page=1
while True:
    payload, headers, url = get(page)
    current_total=0
    all_summaries=[]
    for item in payload:
        source=item.get('source','UNKNOWN')
        if item.get('errors'):
            errors.append({'page':page,'source':source,'errors':item['errors']})
        data=item.get('data') or []
        current_total += len(data)
        if 'summary' in item:
            all_summaries.append({'source':source, **(item.get('summary') or {})})
        for s in data:
            records.append((source,s))
    page_summaries.append({'page':page,'current_records':current_total,'url':url,'summaries':all_summaries})
    print(f'page {page}: {current_total} records')
    # Stop after all data-bearing nodes returned zero current records.
    if current_total == 0:
        break
    page += 1
    if page > 20:
        print('stop at page cap 20')
        break
    time.sleep(0.2)

# de-duplicate records by sample ID first in case overlapping gateway duplicates occur.
unique_samples={}
for source,s in records:
    sk=sample_key(s,source)
    unique_samples.setdefault(sk,(source,s))

patients={}
sample_fallback_count=0
for source,s in unique_samples.values():
    pk=subject_key(s,source)
    if not pk:
        pk=sample_key(s,source)
        sample_fallback_count += 1
    p=patients.setdefault(pk, {'source':source, 'samples':0, 'ages_days':[], 'diagnoses':set(), 'subject_key':pk})
    p['samples'] += 1
    p['ages_days'].extend(parse_age_days(s))
    md=s.get('metadata') or {}
    diag=field_value(md.get('diagnosis'))
    if isinstance(diag, list):
        for d in diag:
            if d: p['diagnoses'].add(str(d))
    elif diag:
        p['diagnoses'].add(str(diag))

# Choose patient age: minimum parseable diagnosis age in days across samples for that subject.
known=[]
missing=[]
conflicts=[]
for pk,p in patients.items():
    vals=sorted(set(round(x,6) for x in p['ages_days'] if x is not None))
    if vals:
        chosen=min(vals)
        known.append((pk, p, chosen, vals))
        if len(vals) > 1:
            # conflict only if ages differ by > 1 day
            if max(vals)-min(vals) > 1:
                conflicts.append((pk,p,vals))
    else:
        missing.append((pk,p))

bins=[('0-<1',0,1),('1-4',1,5),('5-9',5,10),('10-14',10,15),('15-19',15,20),('20+',20,float('inf'))]
bin_counts={b[0]:0 for b in bins}
years=[]
for pk,p,days,vals in known:
    y=days/365.25
    years.append(y)
    for label,lo,hi in bins:
        if y>=lo and y<hi:
            bin_counts[label]+=1
            break

by_source={}
for pk,p in patients.items():
    bs=by_source.setdefault(p['source'], {'patients':0,'known':0,'missing':0,'samples':0})
    bs['patients']+=1; bs['samples']+=p['samples']
for pk,p,days,vals in known:
    by_source[p['source']]['known']+=1
for pk,p in missing:
    by_source[p['source']]['missing']+=1

result={
 'query': {'endpoint':PATH,'params':PARAMS},
 'pages_fetched': page,
 'source_reported_all_counts_page1': {s['source']: s.get('counts',{}).get('all') for s in page_summaries[0]['summaries']},
 'raw_records': len(records),
 'unique_samples': len(unique_samples),
 'deduped_patients_or_sample_fallback': len(patients),
 'sample_fallback_count': sample_fallback_count,
 'known_age_patients': len(known),
 'missing_age_patients': len(missing),
 'bin_counts_years': bin_counts,
 'age_years_summary': {
   'min': min(years) if years else None,
   'max': max(years) if years else None,
   'mean': sum(years)/len(years) if years else None,
   'median': sorted(years)[len(years)//2] if years and len(years)%2 else ((sorted(years)[len(years)//2-1]+sorted(years)[len(years)//2])/2 if years else None)
 },
 'by_source': by_source,
 'age_conflict_patients_gt1day': len(conflicts),
 'node_errors_unique': []
